import Foundation

enum EjtFileVault {
    static var root: URL {
        FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)[0]
    }

    static func slkzresolvePath(_ rel: String) throws -> URL {
        let cleaned = rel.trimmingCharacters(in: CharacterSet(charactersIn: "/"))
        var url = root
        for component in cleaned.split(separator: "/") where !component.isEmpty {
            if component == ".." { continue }
            url = url.appendingPathComponent(String(component), isDirectory: false)
        }
        let rootPath = root.standardizedFileURL.path
        guard url.standardizedFileURL.path.hasPrefix(rootPath) else {
            throw NSError(domain: "EjtFileVault", code: 403)
        }
        return url
    }

    static func iareadData(_ rel: String) throws -> Data {
        try Data(contentsOf: try slkzresolvePath(rel))
    }

    @discardableResult
    static func kwwriteData(_ rel: String, data: Data) throws -> String {
        let url = try slkzresolvePath(rel)
        try FileManager.default.createDirectory(
            at: url.deletingLastPathComponent(),
            withIntermediateDirectories: true
        )
        try data.write(to: url)
        return rel.trimmingCharacters(in: CharacterSet(charactersIn: "/"))
    }
}

enum TbBundleMedia {
    static func data(forRelativePath path: String) -> Data? {
        let trimmed = path.trimmingCharacters(in: CharacterSet(charactersIn: "/"))
        let filename = (trimmed as NSString).lastPathComponent
        guard !filename.isEmpty else { return nil }
        if let data = data(forBundledFilename: filename) {
            return data
        }
        if trimmed != filename, let data = data(forBundledFilename: trimmed) {
            return data
        }
        return nil
    }

    static func data(forBundledFilename filename: String) -> Data? {
        let base = (filename as NSString).deletingPathExtension
        let ext = (filename as NSString).pathExtension
        guard !base.isEmpty, !ext.isEmpty else { return nil }

        let parent = (filename as NSString).deletingLastPathComponent
        var subdirs: [String?] = ["do_seed_bundle_ao", "assets/img"]
        if !parent.isEmpty, parent != "." {
            subdirs.insert(parent, at: 0)
        }
        subdirs.append(nil)

        for directory in subdirs {
            if let directory {
                if let url = Bundle.main.url(forResource: base, withExtension: ext, subdirectory: directory),
                   let data = try? Data(contentsOf: url) {
                    return data
                }
            } else if let url = Bundle.main.url(forResource: base, withExtension: ext),
                      let data = try? Data(contentsOf: url) {
                return data
            }
        }

        guard let resourceURL = Bundle.main.resourceURL else { return nil }
        let leaf = (filename as NSString).lastPathComponent
        let candidates = [
            resourceURL.appendingPathComponent(filename),
            resourceURL.appendingPathComponent("do_seed_bundle_ao").appendingPathComponent(leaf),
            resourceURL.appendingPathComponent("assets/img").appendingPathComponent(leaf),
            resourceURL.appendingPathComponent(leaf),
        ]
        for url in candidates {
            guard FileManager.default.fileExists(atPath: url.path) else { continue }
            if let data = try? Data(contentsOf: url) {
                return data
            }
        }
        return nil
    }
}

import Foundation

enum BbSeedAssets {
    // access: private — bundled dye-care seed rasters (empty until asset pack lands)
    private static let seedFilenames: [String] = []

    /// Copy bundled seed photos into Documents/ik_photos_seed_vk/ (idempotent).
    static func opensureCopied() {
        for filename in seedFilenames {
            let rel = "ik_photos_seed_vk/\(filename)"
            if let url = try? EjtFileVault.slkzresolvePath(rel),
               FileManager.default.fileExists(atPath: url.path) {
                continue
            }
            guard let data = TbBundleMedia.data(forBundledFilename: filename) else {
                continue
            }
            try? EjtFileVault.kwwriteData(rel, data: data)
        }
    }
}

