}

final class MnnyImagePickerCoordinator: NSObject {
    // access: private
    private var completion: ((Result<HfbImagePickResult, Error>) -> Void)?

    func gfnlpresentPicker(
        from vc: UIViewController,
        useCamera: Bool,
        completion: @escaping (_ pickResult: Result<HfbImagePickResult, Error>) -> Void
    ) {
        self.completion = completion

        if useCamera {
            guard UIImagePickerController.isSourceTypeAvailable(.camera) else {
                completion(.failure(NSError(
                    domain: "Tintoo",
                    code: 1,
                    userInfo: [NSLocalizedDescriptionKey: "Camera is unavailable on this device"]
                )))
                return
            }
            let picker = UIImagePickerController()
            picker.sourceType = .camera
            picker.delegate = self
            picker.allowsEditing = false
            vc.present(picker, animated: true)
            return
        }

        var config = PHPickerConfiguration(photoLibrary: .shared())
        config.selectionLimit = 1
        config.filter = .images
        let picker = PHPickerViewController(configuration: config)
        picker.delegate = self
        vc.present(picker, animated: true)
    }

    private func finish(with result: Result<HfbImagePickResult, Error>) {
        completion?(result)
        completion = nil
    }

    private func processImage(_ image: UIImage) {
        guard let data = image.jpegData(compressionQuality: 0.8) else {
            finish(with: .failure(NSError(
                domain: "Tintoo",
                code: 2,
                userInfo: [NSLocalizedDescriptionKey: "Could not encode the tint snapshot"]
            )))
            return
        }
        let rel = "ik_photos_seed_vk/item_\(Int(Date().timeIntervalSince1970)).jpg"
        do {
            let path = try EjtFileVault.kwwriteData(rel, data: data)
            finish(with: .success(HfbImagePickResult(path: path)))
        } catch {
            finish(with: .failure(error))
        }
    }
}

extension MnnyImagePickerCoordinator: UIImagePickerControllerDelegate, UINavigationControllerDelegate {
    func imagePickerController(
        _ picker: UIImagePickerController,
        didFinishPickingMediaWithInfo info: [UIImagePickerController.InfoKey: Any]
    ) {
        picker.dismiss(animated: true)
        if let image = info[.originalImage] as? UIImage {
            processImage(image)
        } else {
            finish(with: .failure(NSError(
                domain: "Tintoo",
                code: 3,
                userInfo: [NSLocalizedDescriptionKey: "No frame was captured"]
            )))
        }
    }

    func imagePickerControllerDidCancel(_ picker: UIImagePickerController) {
        picker.dismiss(animated: true)
        finish(with: .failure(NSError(
            domain: "Tintoo",
            code: 4,
            userInfo: [NSLocalizedDescriptionKey: "Capture cancelled"]
        )))
    }
}

extension MnnyImagePickerCoordinator: PHPickerViewControllerDelegate {
    func picker(_ picker: PHPickerViewController, didFinishPicking results: [PHPickerResult]) {
        picker.dismiss(animated: true)
        guard let provider = results.first?.itemProvider, provider.canLoadObject(ofClass: UIImage.self) else {
            finish(with: .failure(NSError(
                domain: "Tintoo",
                code: 5,
                userInfo: [NSLocalizedDescriptionKey: "No album image selected"]
            )))
            return
        }
        provider.loadObject(ofClass: UIImage.self) { [weak self] object, error in
            DispatchQueue.main.async {
                if let image = object as? UIImage {
                    self?.processImage(image)
                } else {
                    self?.finish(with: .failure(error ?? NSError(
                        domain: "Tintoo",
                        code: 6,
                        userInfo: [NSLocalizedDescriptionKey: "Failed to load album image"]
                    )))
                }
            }
        }
    }
}

