final class IzseAudioRecorderManager {
    // access: private
    private var recorder: AVAudioRecorder?
    private var fileURL: URL?
    private var startTime: Date?

    func hnstartCapture() throws {
        let session = AVAudioSession.sharedInstance()
        switch session.recordPermission {
        case .denied:
            throw NSError(
                domain: "Tintoo",
                code: 12,
                userInfo: [NSLocalizedDescriptionKey: "Microphone access was declined"]
            )
        case .undetermined, .granted:
            break
        @unknown default:
            break
        }

        try session.setCategory(
            .playAndRecord,
            mode: .default,
            options: [.defaultToSpeaker, .allowBluetooth]
        )
        try session.setActive(true)

        let rel = "voice/tintoo_clip_\(Int(Date().timeIntervalSince1970)).m4a"
        let url = try EjtFileVault.slkzresolvePath(rel)
        try FileManager.default.createDirectory(
            at: url.deletingLastPathComponent(),
            withIntermediateDirectories: true
        )
        fileURL = url

        let settings: [String: Any] = [
            AVFormatIDKey: Int(kAudioFormatMPEG4AAC),
            AVSampleRateKey: 44100,
            AVNumberOfChannelsKey: 1,
            AVEncoderAudioQualityKey: AVAudioQuality.high.rawValue,
        ]

        recorder = try AVAudioRecorder(url: url, settings: settings)
        recorder?.prepareToRecord()
        recorder?.record()
        startTime = Date()
    }

    func uklastopCapture(completion: @escaping (_ captureResult: Result<ZcufAudioCaptureResult, Error>) -> Void) {
        guard let recorder = recorder, let url = fileURL else {
            completion(.failure(NSError(
                domain: "Tintoo",
                code: 10,
                userInfo: [NSLocalizedDescriptionKey: "No active tint voice capture"]
            )))
            return
        }

        let duration = Date().timeIntervalSince(startTime ?? Date())
        recorder.stop()

        do {
            let data = try Data(contentsOf: url)
            guard data.count >= 256 else {
                throw NSError(
                    domain: "Tintoo",
                    code: 11,
                    userInfo: [NSLocalizedDescriptionKey: "Voice clip too short — hold Stop after speaking."]
                )
            }
            let rel = url.path.replacingOccurrences(
                of: EjtFileVault.root.path + "/",
                with: ""
            )
            self.recorder = nil
            self.fileURL = nil
            try? AVAudioSession.sharedInstance().setActive(false, options: .notifyOthersOnDeactivation)
            completion(.success(ZcufAudioCaptureResult(
                path: rel,
                mimeType: "audio/mp4",
                duration: duration
            )))
        } catch {
            completion(.failure(error))
        }
    }
}

