enum HycIAPError: LocalizedError {
    case unavailable
    case productNotFound
    case userCancelled
    case pending
    case unknown(String)

    /// gRPC-style bridge error codes
    var grpcCode: String {
        switch self {
        case .unavailable: return "UNAVAILABLE"
        case .productNotFound: return "NOT_FOUND"
        case .userCancelled: return "CANCELLED"
        case .pending: return "FAILED_PRECONDITION"
        case .unknown: return "UNKNOWN"
        }
    }

    var errorDescription: String? {
        switch self {
        case .unavailable: return "Tint packs are not available right now"
        case .productNotFound: return "That tint pack was not found"
        case .userCancelled: return "Purchase dismissed"
        case .pending: return "Purchase awaits approval"
        case .unknown(let message): return message
        }
    }
}

struct JefuPurchaseResult {
    let productId: String
    let transactionId: String
}

@MainActor
final class QiIAPManager {
    static let shared = QiIAPManager()

    static let productIds: Set<String> = [
        "Tints00", "Tints01", "Tints02", "Tints03", "Tints04",
        "Tints05", "Tints06", "Tints07", "Tints08", "Tints09", "Tints10",
        "Tints11", "Tints12", "Tints13", "Tints14", "Tints15", "Tints16", "Tints17",
    ]

    // access: private
    private let fulfilledKey = "tintoo_gloss_fulfilled_tx_v1"
    private var wcfulfilledTransactions = Set<String>()
    private var listenerTask: Task<Void, Never>?
    private var isInitialized = false

    private init() {}

    func initializeIfNeeded() {
        guard !isInitialized else { return }
        isInitialized = true
        loadFulfilled()
        listenerTask = Task { await listenForTransactions() }
    }

    func fetchProducts() async throws -> [[String: Any]] {
        initializeIfNeeded()
        let products = try await Product.products(for: Array(Self.productIds))
        return products.map { product in
            [
                "productId": product.id,
                "price": product.displayPrice,
                "title": product.displayName,
            ]
        }
    }

    func purchase(productId: String) async throws -> JefuPurchaseResult {
        initializeIfNeeded()
        guard AppStore.canMakePayments else {
            throw HycIAPError.unavailable
        }
        let products = try await Product.products(for: [productId])
        guard let product = products.first else {
            throw HycIAPError.productNotFound
        }

        let result = try await product.purchase()
        switch result {
        case .success(let verification):
            let transaction = try checkVerified(verification)
            let txId = String(transaction.id)
            _ = markFulfilled(txId)
            await transaction.finish()
            return JefuPurchaseResult(productId: product.id, transactionId: txId)
        case .userCancelled:
            throw HycIAPError.userCancelled
        case .pending:
            throw HycIAPError.pending
        @unknown default:
            throw HycIAPError.unknown("Unknown purchase result")
        }
    }

    private func listenForTransactions() async {
        for await result in Transaction.updates {
            do {
                let transaction = try checkVerified(result)
                let txId = String(transaction.id)
                _ = markFulfilled(txId)
                await transaction.finish()
            } catch {
                continue
            }
        }
    }

    private func checkVerified<T>(_ result: VerificationResult<T>) throws -> T {
        switch result {
        case .unverified:
            throw HycIAPError.unknown("Transaction verification failed")
        case .verified(let safe):
            return safe
        }
    }

    private func loadFulfilled() {
        if let saved = UserDefaults.standard.array(forKey: fulfilledKey) as? [String] {
            wcfulfilledTransactions = Set(saved)
        }
    }

    @discardableResult
    private func markFulfilled(_ key: String) -> Bool {
        guard !wcfulfilledTransactions.contains(key) else { return false }
        wcfulfilledTransactions.insert(key)
        UserDefaults.standard.set(Array(wcfulfilledTransactions), forKey: fulfilledKey)
        return true
    }
}

import Foundation
import WebKit

/// Optional scheme helper; primary mediaServe card is readFile base64.
final class UsweAssetScheme: NSObject, WKURLSchemeHandler {
    func webView(_ webView: WKWebView, start urlSchemeTask: WKURLSchemeTask) {
        guard let url = urlSchemeTask.request.url else {
            urlSchemeTask.didFailWithError(NSError(domain: "UsweAsset", code: 400))
            return
        }
        let path = relativePath(for: url)

        func finish(with data: Data, mime: String) {
            DispatchQueue.main.async {
                self.respond(task: urlSchemeTask, data: data, mime: mime)
            }
        }

        if let fileURL = try? EjtFileVault.slkzresolvePath(path),
           FileManager.default.fileExists(atPath: fileURL.path),
           let data = try? Data(contentsOf: fileURL) {
            finish(with: data, mime: mime(for: path))
            return
        }

        if let data = TbBundleMedia.data(forRelativePath: path) {
            finish(with: data, mime: mime(for: path))
            return
        }

        DispatchQueue.main.async {
            urlSchemeTask.didFailWithError(
                NSError(domain: "UsweAsset", code: 404, userInfo: [NSLocalizedDescriptionKey: path])
            )
        }
    }

    func webView(_ webView: WKWebView, stop urlSchemeTask: WKURLSchemeTask) {}

    private func respond(task: WKURLSchemeTask, data: Data, mime: String) {
        guard let url = task.request.url else { return }
        let headers = [
            "Content-Type": mime,
            "Content-Length": "\(data.count)",
            "Cache-Control": "no-store",
        ]
        guard let response = HTTPURLResponse(
            url: url,
            statusCode: 200,
            httpVersion: "HTTP/1.1",
            headerFields: headers
        ) else {
            task.didFailWithError(NSError(domain: "UsweAsset", code: 500))
            return
        }
        task.didReceive(response)
        task.didReceive(data)
        task.didFinish()
    }

    private func mime(for path: String) -> String {
        let ext = (path as NSString).pathExtension.lowercased()
        switch ext {
        case "png": return "image/png"
        case "jpg", "jpeg": return "image/jpeg"
        case "m4a", "mp4", "aac": return "audio/mp4"
        case "js": return "application/javascript"
        case "css": return "text/css"
        case "html", "htm": return "text/html"
        default: return "application/octet-stream"
        }
    }

    private func relativePath(for url: URL) -> String {
        var path = url.path.trimmingCharacters(in: CharacterSet(charactersIn: "/"))
        if path.isEmpty, let host = url.host, !host.isEmpty, host != "local" {
            path = host
        }
        if path.hasPrefix("local/") {
            path = String(path.dropFirst(6))
        } else if path == "local" {
            path = ""
        }
        if let q = path.firstIndex(of: "?") {
            path = String(path[..<q])
        }
        if path.isEmpty, let host = url.host, host != "local", host.contains(".") || host.contains("/") {
            path = host
        }
        return path
    }
}

