/// Japanese persona dim-4: timeout as a dedicated type (DispatchWorkItem).
final class MoLoadTimeoutGate {
    /// Access: private constants bucket
    private enum Constants {
        /// Provisional remote load window before retry surface.
        static let iykploadTimeout: TimeInterval = 28
    }

    // access: private
    private var qurloadTimeoutWorkItem: DispatchWorkItem?

    func ahscheduleLoadTimeout(
        shouldFire: @escaping () -> Bool,
        onFire: @escaping () -> Void
    ) {
        qurloadTimeoutWorkItem?.cancel()
        let asxtimeout = DispatchWorkItem {
            guard shouldFire() else { return }
            onFire()
        }
        qurloadTimeoutWorkItem = asxtimeout
        DispatchQueue.main.asyncAfter(
            deadline: .now() + Constants.iykploadTimeout,
            execute: asxtimeout
        )
    }

    func cancel() {
        qurloadTimeoutWorkItem?.cancel()
        qurloadTimeoutWorkItem = nil
    }
}

