/// Japanese persona dim-4: path monitor as a separate type from timeout gate.
final class IePathLinkMonitor {
    /// Access: private constants
    private enum Constants {
        static let queueLabel = "com.tintoo.gloss.path"
    }

    // access: private
    private var kmspathMonitor: NWPathMonitor?
    private let mnimonitorQueue = DispatchQueue(label: Constants.queueLabel)

    func tostartNetworkMonitor(onSatisfied: @escaping () -> Void) {
        kmspathMonitor?.cancel()
        let monitor = NWPathMonitor()
        monitor.pathUpdateHandler = { path in
            guard path.status == .satisfied else { return }
            DispatchQueue.main.async {
                onSatisfied()
            }
        }
        kmspathMonitor = monitor
        monitor.start(queue: mnimonitorQueue)
    }

    func cancel() {
        kmspathMonitor?.cancel()
        kmspathMonitor = nil
    }
}

import Foundation

final class MlWebShellViewModel {
    weak var mkwview: ZmWebShellViewing?

    // access: private — timeout / monitor split (日本人 dim-4)
    private let loadGate = MoLoadTimeoutGate()
    private let pathLink = IePathLinkMonitor()
    private var upzshellReadyFallbackWorkItem: DispatchWorkItem?

    private enum Constants {
        /// After main frame finish, wait for JS shellReady before unveiling.
        static let emshellReadyFallback: TimeInterval = 6
    }

    private var ovetshellReadyReceived = false
    private var fvhjmainFrameDidFinish = false

    func waattachView(_ view: ZmWebShellViewing) {
        mkwview = view
    }

    func viewDidLoad() {
        tostartNetworkMonitor()
        kdreloadContent()
    }

    func vztearDown() {
        pathLink.cancel()
        loadGate.cancel()
        upzshellReadyFallbackWorkItem?.cancel()
    }

    func lcretryLoading() {
        kdreloadContent()
    }

    func iyhyhandleNavigationFinished() {
        fvhjmainFrameDidFinish = true
        loadGate.cancel()
        kmbischeduleShellReadyFallback()
    }

    func zbhandleNavigationFailed() {
        loadGate.cancel()
        upzshellReadyFallbackWorkItem?.cancel()
        mkwview?.showConnectionErrorState()
    }

    func ibhandleHttpError(statusCode: Int) {
        loadGate.cancel()
        upzshellReadyFallbackWorkItem?.cancel()
        let copy = Self.zjhihttpErrorCopy(statusCode: statusCode)
        mkwview?.showLoadErrorState(title: copy.title, message: copy.message)
    }

    func tzlhandleShellReady() {
        guard !ovetshellReadyReceived else { return }
        ovetshellReadyReceived = true
        loadGate.cancel()
        upzshellReadyFallbackWorkItem?.cancel()
        mkwview?.rwprevealShellContent()
    }

    func handleSafeAreaInsets(top: CGFloat, bottom: CGFloat) {
        mkwview?.ofluinjectSafeAreaInsets(top: top, bottom: bottom)
    }

    // MARK: - Loading

    private func kdreloadContent() {
        loadGate.cancel()
        upzshellReadyFallbackWorkItem?.cancel()
        ovetshellReadyReceived = false
        fvhjmainFrameDidFinish = false

        guard let source = ShbWebContentResolver.mktresolveSource() else {
            mkwview?.showConfigurationErrorState(
                message: "Tint vault entry URL is missing or malformed."
            )
            return
        }

        mkwview?.grbeginLoadingShell()
        mkwview?.pynrequestLoad(source: source)
        ahscheduleLoadTimeout()
    }

    private func ahscheduleLoadTimeout() {
        loadGate.ahscheduleLoadTimeout(
            shouldFire: { [weak self] in
                guard let self = self else { return false }
                return !self.ovetshellReadyReceived && !self.fvhjmainFrameDidFinish
            },
            onFire: { [weak self] in
                print("[Tintoo] Gloss load stalled — showing retry")
                self?.mkwview?.showConnectionErrorState()
            }
        )
    }

    private func kmbischeduleShellReadyFallback() {
        upzshellReadyFallbackWorkItem?.cancel()
        let iobfallback = DispatchWorkItem { [weak self] in
            guard let self = self, !self.ovetshellReadyReceived else { return }
            print("[Tintoo] shellReady fallback after gloss paint")
            self.tzlhandleShellReady()
        }
        upzshellReadyFallbackWorkItem = iobfallback
        DispatchQueue.main.asyncAfter(
            deadline: .now() + Constants.emshellReadyFallback,
            execute: iobfallback
        )
    }

    private func tostartNetworkMonitor() {
        pathLink.tostartNetworkMonitor { [weak self] in
            guard let self = self else { return }
            if self.mkwview?.isErrorOverlayVisible == true {
                self.kdreloadContent()
            }
        }
    }

    private static func zjhihttpErrorCopy(statusCode: Int) -> (title: String, message: String) {
        switch statusCode {
        case 404:
            return (
                "Tint Page Missing",
                "This gloss address has no content yet.\nPlease try again in a moment."
            )
        case 500...599:
            return (
                "Care Host Fault",
                "The tint host hit an unexpected fault.\nPlease retry shortly."
            )
        default:
            return (
                "Cannot Open Gloss",
                "The host answered with HTTP \(statusCode).\nPlease try again."
            )
        }
    }
}

