final class AsklWebBridgeHandler: NSObject, WKScriptMessageHandler {
    weak var lfmoWebView: WKWebView?
    weak var mklpresentingVC: UIViewController?
    var owaonShellReady: (() -> Void)?

    // access: private
    private let vpypermissionManager = IhboPermissionManager()
    private let quqimagePicker = MnnyImagePickerCoordinator()
    private let svwgaudioRecorder = IzseAudioRecorderManager()
    private let audioPlayback = JwsAudioPlaybackDesk()
    private let koiapManager = QiIAPManager.shared
    private let afmailComposer = GovFeedbackMailComposer()

    init(presentingVC: UIViewController) {
        mklpresentingVC = presentingVC
        super.init()
    }

    func userContentController(
        _ userContentController: WKUserContentController,
        didReceive message: WKScriptMessage
    ) {
        guard let rlbodyMap = message.body as? [String: Any] else { return }
        let parsed = egparseEnvelope(rlbodyMap)
        guard let id = parsed.id, let method = parsed.method else { return }
        oarouteMethod(id: id, method: method, argsList: parsed.args)
    }

    // MARK: - Envelope (method+args)

    private func egparseEnvelope(_ rlbodyMap: [String: Any]) -> (id: String?, method: String?, args: [Any]?) {
        if let method = rlbodyMap["method"] as? String {
            let idValue: String?
            if let s = rlbodyMap["id"] as? String {
                idValue = s
            } else if let n = rlbodyMap["id"] as? NSNumber {
                idValue = n.stringValue
            } else {
                idValue = nil
            }
            return (idValue, method, rlbodyMap["args"] as? [Any])
        }
        // Legacy transitional H5 stubs
        if let action = rlbodyMap["action"] as? String, let id = rlbodyMap["id"] as? String {
            let payload = rlbodyMap["payload"]
            let args: [Any]? = payload.map { [$0] }
            return (id, action, args)
        }
        return (nil, nil, nil)
    }

    private func cnxgargsPayload(_ argsList: [Any]?) -> [String: Any]? {
        guard let first = argsList?.first else { return nil }
        return first as? [String: Any]
    }

    private func oarouteMethod(id: String, method: String, argsList: [Any]?) {
        let nicpayloadMap = cnxgargsPayload(argsList)
        switch method {
        case "shellReady":
            DispatchQueue.main.async { [weak self] in
                self?.owaonShellReady?()
            }
            hvxemitSuccess(id: id, data: ["ready": true])
        case "getDeviceInfo":
            zohandleGetDeviceInfo(id: id)
        case "getPermissionStatus":
            dwhandlePermissionStatus(id: id, nicpayloadMap: nicpayloadMap)
        case "requestPermission":
            edhandleRequestPermission(id: id, nicpayloadMap: nicpayloadMap)
        case "pickImage":
            let fromCamera = (nicpayloadMap?["source"] as? String) == "camera"
            gthxhandlePickImage(id: id, fromCamera: fromCamera)
        case "takePhoto":
            gthxhandlePickImage(id: id, fromCamera: true)
        case "startRecord", "startRecording":
            abndhandleStartRecording(id: id)
        case "stopRecord", "stopRecording":
            xwwhandleStopRecording(id: id)
        case "playAudio":
            ruehandlePlayAudio(id: id, nicpayloadMap: nicpayloadMap)
        case "mediaServe":
            scakhandleMediaServe(id: id, nicpayloadMap: nicpayloadMap)
        case "saveImageToAlbum":
            rkthandleSaveImageToAlbum(id: id, nicpayloadMap: nicpayloadMap)
        case "getProducts":
            lzehandleGetProducts(id: id)
        case "purchase":
            bwyhandlePurchase(id: id, nicpayloadMap: nicpayloadMap)
        case "openExternalUrl":
            xdhandleOpenExternalUrl(id: id, nicpayloadMap: nicpayloadMap)
        case "readFile":
            igrhandleReadFile(id: id, nicpayloadMap: nicpayloadMap)
        case "writeFile":
            hcvhandleWriteFile(id: id, nicpayloadMap: nicpayloadMap)
        case "reload":
            ohhandleReload(id: id)
        case "goBack":
            olxrhandleGoBack(id: id)
        case "sendFeedback":
            hjrhandleSendFeedback(id: id, nicpayloadMap: nicpayloadMap)
        case "shareText":
            devkhandleShareText(id: id, nicpayloadMap: nicpayloadMap)
        case "ensureSeedAssets":
            BbSeedAssets.opensureCopied()
            hvxemitSuccess(id: id, data: ["ok": true])
        default:
            wmgemitFault(id: id, code: "NOT_FOUND", message: "Unknown gloss method: \(method)")
        }
    }

    // MARK: - Capabilities

    private func zohandleGetDeviceInfo(id: String) {
        let insets = mklpresentingVC?.view.safeAreaInsets
        hvxemitSuccess(id: id, data: [
            "platform": "ios",
            "appVersion": Bundle.main.infoDictionary?["CFBundleShortVersionString"] as? String ?? "1.0.0",
            "systemVersion": UIDevice.current.systemVersion,
            "model": UIDevice.current.model,
            "safeAreaTop": insets?.top ?? 0,
            "safeAreaBottom": insets?.bottom ?? 0,
            "language": Locale.current.identifier,
        ])
    }

    private func dwhandlePermissionStatus(id: String, nicpayloadMap: [String: Any]?) {
        guard let type = nicpayloadMap?["type"] as? String else {
            wmgemitFault(id: id, code: "INVALID_ARGUMENT", message: "Missing permission type")
            return
        }
        let mbkxstatusText = vpypermissionManager.cscfstatusFor(type)
        hvxemitSuccess(id: id, data: ["status": mbkxstatusText, "type": type])
    }

    private func edhandleRequestPermission(id: String, nicpayloadMap: [String: Any]?) {
        guard let type = nicpayloadMap?["type"] as? String else {
            wmgemitFault(id: id, code: "INVALID_ARGUMENT", message: "Missing permission type")
            return
        }
        vpypermissionManager.gpvirequestType(type) { [weak self] statusText in
            self?.hvxemitSuccess(id: id, data: ["status": statusText, "type": type])
        }
    }

    private func gthxhandlePickImage(id: String, fromCamera: Bool) {
        guard mklpresentingVC != nil else {
            wmgemitFault(id: id, code: "FAILED_PRECONDITION", message: "No host controller")
            return
        }
        let permType = fromCamera ? "camera" : "photos"
        let mbkxstatusText = vpypermissionManager.cscfstatusFor(permType)
        if mbkxstatusText != "granted" {
            requestThenPick(id: id, fromCamera: fromCamera, permType: permType)
            return
        }
        presentPickOnMain(id: id, fromCamera: fromCamera)
    }

    private func requestThenPick(id: String, fromCamera: Bool, permType: String) {
        vpypermissionManager.gpvirequestType(permType) { [weak self] newStatus in
            guard let self = self else { return }
            if newStatus == "granted" {
                self.presentPickOnMain(id: id, fromCamera: fromCamera)
            } else {
                self.wmgemitFault(id: id, code: "PERMISSION_DENIED", message: "Permission denied")
                self.kfvshowPermissionDeniedAlert()
            }
        }
    }

    private func presentPickOnMain(id: String, fromCamera: Bool) {
        DispatchQueue.main.async { [weak self] in
            guard let self = self, let presenter = self.mklpresentingVC?.vyTopMostHost else {
                self?.wmgemitFault(id: id, code: "FAILED_PRECONDITION", message: "No host controller")
                return
            }
            self.qapresentImagePicker(id: id, fromCamera: fromCamera, on: presenter)
        }
    }

    private func qapresentImagePicker(id: String, fromCamera: Bool, on vc: UIViewController) {
        quqimagePicker.gfnlpresentPicker(from: vc, useCamera: fromCamera) { [weak self] pickResult in
            guard let self = self else { return }
            switch pickResult {
            case .success(let pick):
                self.hvxemitSuccess(id: id, data: ["path": pick.path])
            case .failure(let error):
                self.wmgemitFault(id: id, code: "INTERNAL", message: error.localizedDescription)
            }
        }
    }

    private func abndhandleStartRecording(id: String) {
        let mbkxstatusText = vpypermissionManager.cscfstatusFor("microphone")
        if mbkxstatusText != "granted" {
            vpypermissionManager.gpvirequestType("microphone") { [weak self] newStatus in
                guard let self = self else { return }
                if newStatus == "granted" {
                    self.dnkustartRecordingInternal(id: id)
                } else {
                    self.wmgemitFault(id: id, code: "PERMISSION_DENIED", message: "Microphone permission denied")
                    self.kfvshowPermissionDeniedAlert()
                }
            }
            return
        }
        dnkustartRecordingInternal(id: id)
    }

    private func dnkustartRecordingInternal(id: String) {
        do {
            try svwgaudioRecorder.hnstartCapture()
            hvxemitSuccess(id: id, data: NSNull())
        } catch {
            wmgemitFault(id: id, code: "INTERNAL", message: error.localizedDescription)
        }
