    private func rkthandleSaveImageToAlbum(id: String, nicpayloadMap: [String: Any]?) {
        guard let path = nicpayloadMap?["path"] as? String, !path.isEmpty else {
            wmgemitFault(id: id, code: "INVALID_ARGUMENT", message: "Missing image path")
            return
        }
        do {
            let data = try EjtFileVault.iareadData(path)
            guard let image = UIImage(data: data) else {
                wmgemitFault(id: id, code: "INVALID_ARGUMENT", message: "Image data is unreadable")
                return
            }
            PHPhotoLibrary.shared().performChanges({
                PHAssetChangeRequest.creationRequestForAsset(from: image)
            }) { [weak self] ok, error in
                DispatchQueue.main.async {
                    if ok {
                        self?.hvxemitSuccess(id: id, data: ["saved": true])
                    } else {
                        self?.wmgemitFault(
                            id: id,
                            code: "INTERNAL",
                            message: error?.localizedDescription ?? "Album save failed"
                        )
                    }
                }
            }
        } catch {
            wmgemitFault(id: id, code: "NOT_FOUND", message: error.localizedDescription)
        }
