    private func devkhandleShareText(id: String, nicpayloadMap: [String: Any]?) {
        guard let text = nicpayloadMap?["text"] as? String,
              let filename = nicpayloadMap?["filename"] as? String,
              let vc = mklpresentingVC else {
            wmgemitFault(id: id, code: "INVALID_ARGUMENT", message: "Invalid share payload")
            return
        }
        let url = FileManager.default.temporaryDirectory.appendingPathComponent(filename)
        do {
            try text.write(to: url, atomically: true, encoding: .utf8)
            let activity = UIActivityViewController(activityItems: [url], applicationActivities: nil)
            if let popover = activity.popoverPresentationController {
                popover.sourceView = vc.view
                popover.sourceRect = CGRect(x: vc.view.bounds.midX, y: vc.view.bounds.midY, width: 0, height: 0)
            }
            DispatchQueue.main.async { [weak self] in
                vc.vyTopMostHost.present(activity, animated: true) {
                    self?.hvxemitSuccess(id: id, data: ["success": true])
                }
            }
        } catch {
            wmgemitFault(id: id, code: "INTERNAL", message: error.localizedDescription)
        }
    }

