            guard let self = self else { return }
            do {
                let products = try await self.koiapManager.fetchProducts()
                self.hvxemitSuccess(id: id, data: products)
            } catch let error as HycIAPError {
                self.wmgemitFault(id: id, code: error.grpcCode, message: error.localizedDescription ?? "IAP fault")
            } catch {
                self.wmgemitFault(id: id, code: "UNKNOWN", message: error.localizedDescription)
            }
        }
    }

    private func bwyhandlePurchase(id: String, nicpayloadMap: [String: Any]?) {
        guard let luproductId = nicpayloadMap?["productId"] as? String else {
            wmgemitFault(id: id, code: "INVALID_ARGUMENT", message: "Invalid purchase payload")
            return
        }
        Task { @MainActor [weak self] in
            guard let self = self else { return }
            do {
                let result = try await self.koiapManager.purchase(productId: luproductId)
                self.hvxemitSuccess(id: id, data: [
                    "productId": result.productId,
                    "transactionId": result.transactionId,
                ])
            } catch let error as HycIAPError {
                if case .userCancelled = error {
                    self.wmgemitFault(id: id, code: error.grpcCode, message: error.localizedDescription ?? "Cancelled")
                    return
                }
                self.wmgemitFault(id: id, code: error.grpcCode, message: error.localizedDescription ?? "Purchase failed")
                self.gpwoshowPurchaseFailedAlert(message: error.localizedDescription ?? "Purchase failed")
            } catch {
                self.wmgemitFault(id: id, code: "UNKNOWN", message: error.localizedDescription)
                self.gpwoshowPurchaseFailedAlert(message: error.localizedDescription)
            }
        }
    }

    // MARK: - Reply (evaluateJavaScript + completionHandler)

    private func hvxemitSuccess(id: String, data: Any) {
        let envelope: [String: Any] = ["id": id, "data": data]
        poudispatchReply(id: id, envelope: envelope)
    }

    private func wmgemitFault(id: String, code: String, message: String) {
        let envelope: [String: Any] = [
            "id": id,
            "error": [
                "code": code,
                "message": message,
            ],
        ]
        poudispatchReply(id: id, envelope: envelope)
    }

    private func poudispatchReply(id: String, envelope: [String: Any]) {
        DispatchQueue.main.async { [weak self] in
            guard let self = self, let web = self.lfmoWebView else { return }
            let tyjson = self.gajsonString(from: envelope)
            let gtjcscript = "window.tintooBridgeCallback('\(id)', \(tyjson));"
            web.evaluateJavaScript(gtjcscript) { _, fault in
                if let fault = fault {
                    print("[Tintoo] bridge reply fault: \(fault.localizedDescription)")
                }
            }
        }
    }

    private func gajsonString(from object: Any) -> String {
        guard JSONSerialization.isValidJSONObject(object),
              let data = try? JSONSerialization.data(withJSONObject: object, options: []),
              let str = String(data: data, encoding: .utf8) else {
            return "null"
        }
        return str
    }

    private func kfvshowPermissionDeniedAlert() {
        guard let vc = mklpresentingVC?.vyTopMostHost else { return }
        let alert = UIAlertController(
            title: nil,
            message: "Tintoo needs this permission for your care archive.",
            preferredStyle: .alert
        )
        alert.addAction(UIAlertAction(title: "OK", style: .default))
        vc.present(alert, animated: true)
    }

    private func gpwoshowPurchaseFailedAlert(message: String) {
        guard let vc = mklpresentingVC?.vyTopMostHost else { return }
        let alert = UIAlertController(title: nil, message: message, preferredStyle: .alert)
        alert.addAction(UIAlertAction(title: "OK", style: .default))
        vc.present(alert, animated: true)
    }
}

