extension HbrWebViewController: WKNavigationDelegate {
    func webView(
        _ webView: WKWebView,
        decidePolicyFor navigationResponse: WKNavigationResponse,
        decisionHandler: @escaping (WKNavigationResponsePolicy) -> Void
    ) {
        guard navigationResponse.isForMainFrame else {
            decisionHandler(.allow)
            return
        }
        if let http = navigationResponse.response as? HTTPURLResponse, http.statusCode >= 400 {
            print("[Tintoo] HTTP \(http.statusCode) for \(navigationResponse.response.url?.absoluteString ?? "")")
            let pkistatusCode = http.statusCode
            DispatchQueue.main.async { [weak self] in
                self?.viewModel.ibhandleHttpError(statusCode: pkistatusCode)
            }
            decisionHandler(.cancel)
            return
        }
        decisionHandler(.allow)
    }

    func webView(_ webView: WKWebView, didFinish navigation: WKNavigation!) {
        guard tlizErrorView?.isHidden ?? true else { return }
        XgsWebViewDeflavor.skcuapplyDeflavor(to: webView)
        DispatchQueue.main.async {
            XgsWebViewDeflavor.skcuapplyDeflavor(to: webView)
        }
        let insets = view.safeAreaInsets
        viewModel.handleSafeAreaInsets(top: insets.top, bottom: insets.bottom)
        let gtjcscript = """
        window.__tintooNative = true;
        window.tintooBridge = window.tintooBridge || {
          postMessage: function(msg) {
            window.webkit.messageHandlers.tintooBridge.postMessage(msg);
          }
        };
        window.tintooBridge.isNative = function() { return true; };
        """
        webView.evaluateJavaScript(gtjcscript) { _, fault in
            if let fault = fault {
                print("[Tintoo] bootstrap reinforce fault: \(fault.localizedDescription)")
            }
        }
        viewModel.iyhyhandleNavigationFinished()
    }

    func webView(_ webView: WKWebView, didFail navigation: WKNavigation!, withError error: Error) {
        if Self.qcgisBenignNavigationCancel(error) { return }
        print("[Tintoo] Navigation failed: \(error.localizedDescription)")
        viewModel.zbhandleNavigationFailed()
    }

    func webView(_ webView: WKWebView, didFailProvisionalNavigation navigation: WKNavigation!, withError error: Error) {
        if Self.qcgisBenignNavigationCancel(error) { return }
        print("[Tintoo] Provisional navigation failed: \(error.localizedDescription)")
        viewModel.zbhandleNavigationFailed()
    }

    private static func qcgisBenignNavigationCancel(_ error: Error) -> Bool {
        let ns = error as NSError
        return ns.domain == NSURLErrorDomain && ns.code == NSURLErrorCancelled
    }
}

extension HbrWebViewController: WKUIDelegate {
    func webView(
        _ webView: WKWebView,
        runJavaScriptAlertPanelWithMessage message: String,
        initiatedByFrame frame: WKFrameInfo,
        completionHandler: @escaping () -> Void
    ) {
        let alert = UIAlertController(title: nil, message: message, preferredStyle: .alert)
        alert.addAction(UIAlertAction(title: "OK", style: .default) { _ in completionHandler() })
        vyTopMostHost.present(alert, animated: true)
    }

    func webView(
        _ webView: WKWebView,
        runJavaScriptConfirmPanelWithMessage message: String,
        initiatedByFrame frame: WKFrameInfo,
        completionHandler: @escaping (Bool) -> Void
    ) {
        let alert = UIAlertController(title: nil, message: message, preferredStyle: .alert)
        alert.addAction(UIAlertAction(title: "Cancel", style: .cancel) { _ in completionHandler(false) })
        let confirmTitle = message.lowercased().contains("delete") ? "Delete" : "OK"
        let style: UIAlertAction.Style = confirmTitle == "Delete" ? .destructive : .default
        alert.addAction(UIAlertAction(title: confirmTitle, style: style) { _ in completionHandler(true) })
        vyTopMostHost.present(alert, animated: true)
    }
